(()=>{'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(v,d=1)=>typeof v==='number'&&Number.isFinite(v)?new Intl.NumberFormat('es-MX',{maximumFractionDigits:d}).format(v):'—';
const API=String(window.GROWA_WATER_API||'').replace(/\/$/,''),colors=['#64854a','#c08645','#5a8293','#9a6f8c'];
let catalog=[],generation=0,abort=null,map=null,markers=new Map(),mapLayer=null,selected=null,summary=null,compareIds=[],mapExpanded=false;
let S={dataset:'presas',state:'Sinaloa',metric:'namo',from:'',to:'',q:'',view:'map',page:1,sort:'name',direction:'asc',entity:'',bbox:''};
const params=new URLSearchParams(location.search);for(const k of Object.keys(S))if(params.has(k))S[k]=params.get(k);S.page=Math.max(1,Number(S.page)||1);compareIds=(params.get('entities')||'').split(',').filter(Boolean).slice(0,4);
const current=()=>catalog.find(x=>x.id===S.dataset)||catalog[0];
function query(extra={}){const p=new URLSearchParams();Object.entries({...S,entities:S.view==='compare'?compareIds.join(','):'',...extra}).forEach(([k,v])=>{if(v!==''&&v!==undefined&&v!==null)p.set(k,String(v))});return p.toString()}
async function request(path,extra={},signal=abort?.signal){const r=await fetch(API+'/api/'+path+'?'+query({entity:'',...extra}),{signal});let j;try{j=await r.json()}catch(e){throw Error('La API no devolvió una respuesta válida. Intente de nuevo.')}if(!r.ok)throw Error(j.error||'No se pudo consultar la fuente');return j}
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,3800)}
function fail(e){if(e.name==='AbortError')return;$('error').textContent=e.message;$('error').hidden=false;$('query-status').textContent='Consulta pendiente';$('analysis').setAttribute('aria-busy','false')}
function releaseMap(){if(map){map.remove();map=null;markers.clear();mapLayer=null}mapExpanded=false}
function empty(title,text,actions=''){return `<div class="no-data"><div><span class="empty-icon" aria-hidden="true">⊞</span><h2>${esc(title)}</h2><p>${esc(text)}</p>${actions}</div></div>`}
function note(){return `<div class="source-note">${esc(current().description)}</div>`}
function rememberURL(){try{history.replaceState(null,'','?'+query());}catch(e){}}
function renderLibrary(){let category='';$('datasets').innerHTML=catalog.map(d=>{let heading=d.category!==category?`<div class="library-section"><span>${esc(d.category.toUpperCase())}</span></div>`:'';category=d.category;const icons={catalog:'◉',snapshot:'◈',series:'⌁',undated:'◌',analysis:'↗',metadata:'▤'};return heading+`<button class="dataset-button" data-dataset="${d.id}" aria-current="${d.id===S.dataset?'page':'false'}"><span class="dataset-icon" aria-hidden="true">${icons[d.kind]}</span><span class="dataset-name">${esc(d.title)}</span><small>${fmt(d.records,0)}</small></button>`}).join('')}
function controls(){const d=current();if(!d.columns[S.metric])S.metric=d.metric;$('dataset-title').textContent=d.title;$('category').textContent=d.category.toUpperCase();$('dataset-kind').textContent=({catalog:'INVENTARIO TERRITORIAL',snapshot:'BALANCE ADMINISTRATIVO',series:'SERIE HISTÓRICA',undated:'OBSERVACIONES SIN FECHA',analysis:'ESTIMACIONES DOCUMENTALES',metadata:'METADATOS DE COBERTURA'})[d.kind];$('dataset-description').textContent=d.description;
$('state').innerHTML='<option value="all">Todas las entidades</option>'+d.states.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');if(!d.states.includes(S.state))S.state='all';$('state').value=S.state;
$('metric').innerHTML=Object.entries(d.columns).map(([k,v])=>`<option value="${k}">${esc(v[0])} · ${esc(v[1])}</option>`).join('');$('metric').value=S.metric;
const temporal=d.kind==='series';$('from').disabled=!temporal;$('to').disabled=!temporal;if(!temporal){S.from='';S.to=''}$('from').value=S.from;$('to').value=S.to;$('from').placeholder=temporal?d.start?.slice(0,4)||'Inicio':'No aplica';$('to').placeholder=temporal?d.end?.slice(0,4)||'Fin':'No aplica';$('search').value=S.q;
$('source-footnote').textContent=d.kind==='metadata'?'Metadatos declarados · observaciones no materializadas':'Archivo integrado · datos consultados en servidor';renderLibrary();document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-current',b.dataset.view===S.view?'page':'false'));$('view-caption').textContent={map:'EXPLORACIÓN GEOGRÁFICA',series:'ANÁLISIS TEMPORAL',table:'CONSULTA DE REGISTROS',compare:'COMPARACIÓN DE UNIDADES',catalog:'COBERTURA Y TRAZABILIDAD'}[S.view]||''}
function metrics(x){const temporal=x.start?x.start.slice(0,4)+' — '+x.end.slice(0,4):'Sin fecha';const unit=x.unit;const cards=[['REGISTROS EN LA SELECCIÓN',fmt(x.records,0),'Observaciones materializadas'],['UNIDADES DE OBSERVACIÓN',fmt(x.entities,0),fmt(x.states,0)+(x.states===1?' entidad con registros':' entidades con registros')],['COBERTURA TEMPORAL',temporal,x.start?'Según las fechas de origen':'Inventario o medición sin fecha'],['MEDIA DE LA VARIABLE',fmt(x.mean),unit+' · '+fmt(x.valid,0)+' valores numéricos']];$('metrics').innerHTML=cards.map((c,i)=>`<div><span>${c[0]}</span><strong class="${i===2?'compact':''}">${esc(c[1])}</strong><small>${esc(c[2])}</small></div>`).join('');$('query-description').textContent=`${fmt(x.records,0)} registros · ${S.state==='all'?'todas las entidades':S.state}${S.from||S.to?' · '+(S.from||'inicio')+'–'+(S.to||'fin'):''}${S.q?' · búsqueda: '+S.q:''}`}
async function render(){const token=++generation;abort?.abort();abort=new AbortController();$('error').hidden=true;$('analysis').setAttribute('aria-busy','true');$('query-status').textContent='Consultando';const started=performance.now();controls();rememberURL();releaseMap();try{
summary=await request('summary');if(token!==generation)return;metrics(summary);
if(S.view==='map')await renderMap(token);else if(S.view==='table')await renderTable(token);else if(S.view==='series')await renderSeries(token);else if(S.view==='compare')await renderCompare(token);else renderCatalog();
if(token!==generation)return;$('analysis').setAttribute('aria-busy','false');$('query-status').textContent=Math.round(performance.now()-started)+' ms · API';
}catch(e){fail(e)}}
async function renderMap(token){if(!current().geo){$('analysis').innerHTML=empty('Esta fuente no contiene geometrías verificadas.','Puede explorar sus registros, analizar su serie histórica o consultar la cobertura disponible.',`<button class="button primary" data-view="table">Abrir tabla</button>${current().kind==='series'?'<button class="button" data-view="series">Explorar series</button>':''}`)+note();return}
const geo=await request('map');if(token!==generation)return;
$('analysis').innerHTML=`<div class="map-layout"><div class="map-pane" id="map-pane"><div id="map" class="map-canvas" aria-label="Mapa de los registros filtrados"></div><div class="map-top"><span class="map-pill">INVENTARIO GEOREFERENCIADO</span><span class="map-pill">${esc(S.state==='all'?'MÉXICO':S.state.toUpperCase())}</span></div><div class="map-legend"><small>UBICACIONES DISPONIBLES</small><strong>${fmt(geo.features.length,0)}</strong><span>Tamaño: ${esc(current().columns[S.metric][0])}</span></div><div class="map-actions"><select id="basemap" aria-label="Mapa base"><option value="light">Mapa claro</option><option value="satellite">Satélite</option></select><button data-map="fit">Centrar</button><button data-map="extent" aria-pressed="${Boolean(S.bbox)}">${S.bbox?'Quitar filtro espacial':'Filtrar área visible'}</button><button data-map="expand" aria-pressed="false">Ampliar</button><button data-map="geojson">↓ GeoJSON</button></div></div><div class="map-side"><h3>En el territorio</h3><p>Seleccione una ubicación para abrir su expediente.</p><div class="map-list">${geo.features.map(f=>`<button class="map-item" data-record="${f.properties.id}">${esc(f.properties.name)}<small>${esc(f.properties.municipality||f.properties.state)} · ${fmt(f.properties.fields[S.metric])} ${esc(current().columns[S.metric][1])}</small></button>`).join('')}</div></div></div><div class="map-bottom"><span>Fuente de ubicaciones: inventarios integrados</span><span>Las marcas son puntos, no polígonos de embalse.</span></div>${note()}`;
if(!window.L){$('map').innerHTML='<div class="map-fallback">La biblioteca cartográfica externa no respondió. La selección continúa disponible en tabla.</div>';return}
if(!geo.features.length){$('map').innerHTML=empty('No hay ubicaciones para esta consulta.','Cambie el territorio o restablezca los filtros.');return}
map=L.map('map',{zoomControl:false,preferCanvas:true,scrollWheelZoom:false});L.control.zoom({position:'bottomright'}).addTo(map);setBase('light');const group=L.featureGroup();
geo.features.forEach(f=>{const r=f.properties,value=Number(r.fields[S.metric]),m=L.circleMarker([f.geometry.coordinates[1],f.geometry.coordinates[0]],{radius:Math.max(4,Math.min(13,4+Math.sqrt(Math.abs(value)||0)/11)),weight:1.5,color:'#fff',fillColor:'#6c8a4c',fillOpacity:.87});m._growaRadius=m.options.radius;m.bindTooltip(esc(r.name)+' · '+fmt(r.fields[S.metric])+' '+esc(current().columns[S.metric][1]));m.on('click',()=>inspect(r.id));group.addLayer(m);markers.set(r.id,m)});group.addTo(map);map._growaBounds=group.getBounds();map.fitBounds(group.getBounds().pad(.14),{paddingTopLeft:[10,120],paddingBottomRight:[15,35],maxZoom:10});map._growaGeo=geo;map.invalidateSize();
}
function setBase(type){if(!map)return;if(mapLayer)map.removeLayer(mapLayer);$('map').classList.toggle('satellite',type==='satellite');const sat=type==='satellite';mapLayer=L.tileLayer(sat?'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}':'https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:sat?'Imagery © Esri, Maxar':'© OpenStreetMap contributors'}).addTo(map);let errors=0;mapLayer.on('tileerror',()=>{if(++errors===5)toast('La cartografía externa no respondió; los puntos y la tabla siguen disponibles.')})}
async function renderTable(token){const r=await request('query',{limit:40});if(token!==generation)return;const c=current(),fields=Object.entries(c.columns);$('analysis').innerHTML=`<div class="panel"><div class="table-top"><div><h2>Registros de la selección</h2><small>${fmt(r.total,0)} filas · orden y paginación procesados en servidor</small></div><button class="button" data-download>↓ CSV completo</button></div><div class="data-table-wrap"><table class="data-table"><thead><tr>${[['name','Nombre / unidad'],['state','Entidad'],['date','Fecha']].map(([k,v])=>`<th scope="col"><button data-sort="${k}">${v} ${S.sort===k?(S.direction==='asc'?'↑':'↓'):'↕'}</button></th>`).join('')}${fields.map(([k,v])=>`<th scope="col"><button data-sort="value" data-metric="${k}">${esc(v[0])} · ${esc(v[1])} ${S.sort==='value'&&S.metric===k?(S.direction==='asc'?'↑':'↓'):'↕'}</button></th>`).join('')}<th scope="col">Clave</th></tr></thead><tbody>${r.rows.map(x=>`<tr data-id="${x.id}" tabindex="0" aria-label="Abrir registro ${esc(x.name)}"><td>${esc(x.name)}</td><td>${esc(x.state)}</td><td>${esc(x.date)}</td>${fields.map(([k])=>`<td class="num">${typeof x.fields[k]==='number'?fmt(x.fields[k],3):esc(x.fields[k])}</td>`).join('')}<td>${esc(x.entity)}</td></tr>`).join('')||`<tr><td colspan="${fields.length+4}">No hay registros para los criterios actuales.</td></tr>`}</tbody></table></div><div class="pager"><span>${r.total?fmt((r.page-1)*r.limit+1,0):0}–${fmt(Math.min(r.page*r.limit,r.total),0)} de ${fmt(r.total,0)} · página ${r.page}</span><div><button data-page="-1" ${r.page<=1?'disabled':''}>← Anterior</button><button data-page="1" ${r.page*r.limit>=r.total?'disabled':''}>Siguiente →</button></div></div></div>${note()}`}
function chartSVG(data){const series=data.series;if(!series.length)return empty('Sin serie temporal disponible.',data.reason||'Cambie los filtros o seleccione otra fuente.');const valid=series.flatMap(s=>s.points.filter(p=>typeof p.value==='number'&&Number.isFinite(p.value)));if(!valid.length)return empty('Sin valores numéricos en la selección.','Los registros ausentes no se convierten en cero.');const date=p=>Date.parse(p.date.length===4?p.date+'-01-01':p.date.length===7?p.date+'-01':p.date);const t0=Math.min(...valid.map(date)),t1=Math.max(...valid.map(date));let lo=Math.min(...valid.map(p=>p.value)),hi=Math.max(...valid.map(p=>p.value)),pad=(hi-lo)*.12||1;lo-=pad;hi+=pad;const x=p=>70+(date(p)-t0)/(t1-t0||1)*850,y=v=>235-(v-lo)/(hi-lo)*185;let svg=`<svg viewBox="0 0 960 300" role="img" aria-label="Series de ${esc(current().columns[S.metric][0])} en ${esc(data.unit)}"><title>${esc(current().columns[S.metric][0])} · series separadas sin interpolación</title>`;
for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;svg+=`<line x1="70" x2="920" y1="${y(v)}" y2="${y(v)}" stroke="#e1e8d9"/><text x="56" y="${y(v)+4}" text-anchor="end">${fmt(v,1)}</text>`}
for(let i=0;i<4;i++){const t=t0+(t1-t0)*i/3;svg+=`<text x="${70+850*i/3}" y="270" text-anchor="middle">${new Date(t).toISOString().slice(0,10)}</text>`}
series.forEach((s,idx)=>{let segments=[],segment=[],last=null;s.points.forEach(p=>{if(p.value===null||!Number.isFinite(p.value)){if(segment.length)segments.push(segment);segment=[];last=null;return}if(last&&date(p)-date(last)>data.gap_days*86400000){segments.push(segment);segment=[]}segment.push(p);last=p});if(segment.length)segments.push(segment);segments.forEach(seg=>{svg+=`<polyline fill="none" stroke="${colors[idx]}" stroke-width="2.5" stroke-linejoin="round" points="${seg.map(p=>x(p).toFixed(2)+','+y(p.value).toFixed(2)).join(' ')}"/>`;if(seg.length===1)svg+=`<circle cx="${x(seg[0])}" cy="${y(seg[0].value)}" r="3" fill="${colors[idx]}"/>`});const step=Math.max(1,Math.floor(s.points.length/250));s.points.forEach((p,i)=>{if(p.value!==null&&i%step===0)svg+=`<circle cx="${x(p)}" cy="${y(p.value)}" r="5" fill="transparent" tabindex="0"><title>${esc(s.name)} · ${p.date}: ${fmt(p.value,3)} ${esc(data.unit)}</title></circle>`})});return svg+'</svg>'}
async function renderSeries(token){const c=current();if(c.kind!=='series'){$('analysis').innerHTML=empty('Esta fuente no admite análisis temporal.','No se asignan fechas a inventarios ni a observaciones sin fecha de muestreo.',`<button class="button primary" data-view="table">Consultar observaciones</button><button class="button" data-dataset="mensual">Ver almacenamiento mensual</button>`)+note();return}
if(!summary.entity_options.some(x=>x.id===S.entity))S.entity=summary.entity_options[0]?.id||'';const d=await request('series',{entities:S.entity});if(token!==generation)return;$('analysis').innerHTML=`<div class="panel"><div class="panel-heading"><div><span class="overline">HISTORIA DE LA VARIABLE / ${esc(d.unit)}</span><h2>${esc(c.columns[S.metric][0])}</h2><p>Serie individual. Los huecos temporales interrumpen la línea.</p></div><div class="chart-control"><label>Unidad de observación<select id="series-entity">${summary.entity_options.map(x=>`<option value="${esc(x.id)}" ${S.entity===x.id?'selected':''}>${esc(x.name)} · ${esc(x.id)}</option>`).join('')}</select></label><button class="button" data-view="compare">⇄ Comparar</button></div></div><div class="chart">${chartSVG(d)}</div><div class="chart-caption"><div class="legend">${d.series.map((s,i)=>`<span><i style="background:${colors[i]}"></i>${esc(s.name)}</span>`).join('')}</div><span>${fmt(d.series.reduce((n,s)=>n+s.points.length,0),0)} observaciones · valores de origen</span></div></div>${note()}`}
async function renderCompare(token){const c=current();if(!summary.entity_options.length){$('analysis').innerHTML=empty('Sin unidades para comparar.','Amplíe los filtros o seleccione otra fuente.');return}
compareIds=compareIds.filter(id=>summary.entity_options.some(e=>e.id===id));if(!compareIds.length)compareIds=summary.entity_options.slice(0,Math.min(2,summary.entity_options.length)).map(x=>x.id);const ids=compareIds.join(',');const [cmp,series]=await Promise.all([request('compare',{entities:ids}),request('series',{entities:ids})]);if(token!==generation)return;
$('analysis').innerHTML=`<div class="panel"><div class="panel-heading"><div><span class="overline">COMPARACIÓN / MISMA FUENTE Y VARIABLE</span><h2>Contrastar unidades de observación</h2><p>Seleccione hasta cuatro. Las fechas y la cobertura pueden diferir.</p></div><span class="coverage-label">${compareIds.length} / 4 seleccionadas</span></div><div class="compare-selector">${summary.entity_options.map(e=>`<label class="compare-option"><input type="checkbox" data-compare="${esc(e.id)}" ${compareIds.includes(e.id)?'checked':''}><span>${esc(e.name)}</span><small>${esc(e.id)}</small></label>`).join('')}</div>${c.kind==='series'?`<div class="chart">${chartSVG(series)}</div>`:''}<div class="compare-summary data-table-wrap"><table class="data-table"><thead><tr><th>Unidad</th><th>Observaciones válidas</th><th>Media · ${esc(cmp.unit)}</th><th>Mínimo</th><th>Máximo</th><th>Último dato</th><th>Fecha del último dato</th></tr></thead><tbody>${cmp.rows.map((r,i)=>`<tr><td><span style="color:${colors[i]}">●</span> ${esc(r.name)}</td><td>${fmt(r.observations,0)}</td><td>${fmt(r.mean,3)}</td><td>${fmt(r.minimum,3)}</td><td>${fmt(r.maximum,3)}</td><td>${fmt(r.last,3)}</td><td>${esc(r.last_date)}</td></tr>`).join('')}</tbody></table></div></div><div class="source-note">${esc(cmp.warning)} ${esc(c.description)}</div>`}
function renderCatalog(){$('analysis').innerHTML=`<div class="catalog-grid">${catalog.map(d=>`<article class="catalog-card"><span>${esc(d.category.toUpperCase())}</span><h2>${esc(d.title)}</h2><p>${esc(d.description)}</p><dl><div><dt>Filas materializadas</dt><dd>${fmt(d.records,0)}</dd></div><div><dt>Unidades</dt><dd>${fmt(d.entities,0)}</dd></div><div><dt>Cobertura temporal</dt><dd>${d.start?esc(d.start)+' → '+esc(d.end):'Sin fecha homologada'}</dd></div><div><dt>Ubicaciones</dt><dd>${fmt(d.geolocated,0)} verificables</dd></div></dl><button class="button" data-dataset="${d.id}">Consultar fuente ↗</button></article>`).join('')}</div><div class="source-note">Los registros de cobertura describen archivos documentales; sus cantidades no se suman como observaciones descargadas. Esta plataforma es independiente y no constituye un portal oficial de CONAGUA.</div>`}
async function inspect(id){selected=Number(id);$('inspector').hidden=false;$('inspector-content').innerHTML='<p>Cargando expediente…</p>';try{const r=await request('record',{id},undefined);if(selected!==Number(id))return;const c=current(),pairs=[['Clave de origen',r.entity],['Entidad',r.state],['Municipio',r.municipality],['Fecha',r.date],...Object.entries(r.fields).map(([k,v])=>[c.columns[k]?.[0]||k,typeof v==='number'?fmt(v,4)+' '+(c.columns[k]?.[1]||''):v]),['Latitud',r.lat],['Longitud',r.lon],['Fuente',r.source]];$('inspector-content').innerHTML=`<span class="overline">REGISTRO #${r.id}</span><h2>${esc(r.name)}</h2><p>${esc(r.state)} / ${esc(c.title)}</p><dl>${pairs.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${r.source_url&&/^https:\/\//.test(r.source_url)?`<a target="_blank" rel="noopener noreferrer" href="${esc(r.source_url)}">Consultar documento de origen ↗</a>`:''}<div class="source-note">${esc(c.description)}</div>`;markers.forEach((m,k)=>m.setStyle({fillColor:k===selected?'#c58643':'#6c8a4c',radius:k===selected?Math.max(11,m._growaRadius):m._growaRadius}));if(markers.has(selected)){markers.get(selected).bringToFront();map?.panTo(markers.get(selected).getLatLng())}document.querySelectorAll('[data-record],[data-id]').forEach(e=>e.classList.toggle('selected',Number(e.dataset.record||e.dataset.id)===selected));}catch(e){if(e.name!=='AbortError')$('inspector-content').innerHTML='<p>'+esc(e.message)+'</p>'}}
function changeDataset(id){if(!catalog.some(x=>x.id===id))return;S={...S,dataset:id,metric:catalog.find(x=>x.id===id).metric,page:1,q:'',from:'',to:'',entity:'',bbox:'',sort:'name',direction:'asc'};compareIds=[];$('inspector').hidden=true;document.querySelector('.app').classList.remove('show-library');render()}
function exportCSV(){window.open(API+'/api/export?'+query(),'_blank','noopener')}
function saved(){try{return JSON.parse(localStorage.getItem('growa-water-queries')||'[]')}catch(e){return []}}
function savedUI(){$('saved-views').innerHTML=saved().map((x,i)=>`<div class="saved-item"><button data-saved="${i}">${esc(x.name)}</button><button data-delete-saved="${i}" aria-label="Eliminar consulta ${esc(x.name)}">×</button></div>`).join('')||'<p class="saved-empty">Guarde filtros para volver a su análisis.</p>'}
function share(){let u;try{u=new URL(location.href);if(window.parent!==window){u=new URL(document.referrer||location.href);u.hash='agua';u.search='water='+encodeURIComponent(query())}else{u.search=query()}}catch(e){u=new URL(location.href)}if(navigator.clipboard)navigator.clipboard.writeText(u.href).then(()=>toast('Enlace de la consulta copiado')).catch(()=>toast('No fue posible copiar; use la URL de su navegador.'));else toast('Use la URL de su navegador para compartir esta consulta.')}
document.addEventListener('click',e=>{const ds=e.target.closest('[data-dataset]');if(ds){changeDataset(ds.dataset.dataset);return}const view=e.target.closest('[data-view]');if(view){S.view=view.dataset.view;S.entity='';render();return}const record=e.target.closest('[data-record],[data-id]');if(record){inspect(record.dataset.record||record.dataset.id);return}const page=e.target.closest('[data-page]');if(page){S.page=Math.max(1,Number(S.page)+Number(page.dataset.page));render();return}const sort=e.target.closest('[data-sort]');if(sort){S.direction=S.sort===sort.dataset.sort&&(!sort.dataset.metric||S.metric===sort.dataset.metric)&&S.direction==='asc'?'desc':'asc';S.sort=sort.dataset.sort;if(sort.dataset.metric)S.metric=sort.dataset.metric;S.page=1;render();return}if(e.target.closest('[data-download]')){exportCSV();return}const mapBtn=e.target.closest('[data-map]');if(mapBtn&&map){switch(mapBtn.dataset.map){case'fit':map.fitBounds(map._growaBounds.pad(.14),{maxZoom:10,paddingTopLeft:[10,120],paddingBottomRight:[15,30]});break;case'extent':if(S.bbox)S.bbox='';else{const b=map.getBounds();S.bbox=[b.getWest(),b.getSouth(),b.getEast(),b.getNorth()].join(',')}S.page=1;render();break;case'expand':mapExpanded=!mapExpanded;$('map-pane').classList.toggle('map-expanded',mapExpanded);mapBtn.textContent=mapExpanded?'Cerrar ampliación':'Ampliar';mapBtn.setAttribute('aria-pressed',String(mapExpanded));map.invalidateSize();break;case'geojson':const blob=new Blob([JSON.stringify(map._growaGeo,null,2)],{type:'application/geo+json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='GROWA_presas_filtradas.geojson';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break}return}const sv=e.target.closest('[data-saved]');if(sv){const v=saved()[Number(sv.dataset.saved)];if(v){S={...v.state};compareIds=(S.entities||'').split(',').filter(Boolean).slice(0,4);render()}return}const del=e.target.closest('[data-delete-saved]');if(del){const a=saved();a.splice(Number(del.dataset.deleteSaved),1);try{localStorage.setItem('growa-water-queries',JSON.stringify(a))}catch(e){}savedUI()}});
document.addEventListener('change',e=>{const id=e.target.id;if(['state','metric','from','to'].includes(id)){S[id]=e.target.value;S.page=1;S.entity='';S.bbox='';if(S.from&&S.to&&Number(S.from)>Number(S.to)){toast('El año inicial debe ser menor o igual al final.');return}render()}if(id==='series-entity'){S.entity=e.target.value;render()}if(id==='basemap')setBase(e.target.value);if(e.target.dataset.compare){const id=e.target.dataset.compare;if(e.target.checked){if(compareIds.length===4){e.target.checked=false;toast('Puede comparar hasta cuatro unidades.');return}compareIds.push(id)}else compareIds=compareIds.filter(x=>x!==id);if(!compareIds.length){e.target.checked=true;compareIds=[id];toast('Mantenga al menos una unidad seleccionada.');return}render()}});
let debounce; $('search').addEventListener('input',e=>{S.q=e.target.value;S.page=1;clearTimeout(debounce);debounce=setTimeout(render,280)});$('reset').onclick=()=>{S={...S,state:'all',from:'',to:'',q:'',entity:'',bbox:'',page:1};compareIds=[];render()};$('download').onclick=exportCSV;$('share').onclick=share;$('close-inspector').onclick=()=>$('inspector').hidden=true;$('open-guide').onclick=()=>$('guide').showModal();$('open-method').onclick=$('catalog-shortcut').onclick=()=>{S.view='catalog';render()};$('sidebar-toggle').onclick=()=>{const open=document.querySelector('.app').classList.toggle('show-library');$('sidebar-toggle').setAttribute('aria-expanded',String(open))};$('save-view').onclick=()=>{const name=current().title+' · '+(S.state==='all'?'México':S.state);const list=saved();list.unshift({name,state:{...S,entities:compareIds.join(',')}});try{localStorage.setItem('growa-water-queries',JSON.stringify(list.slice(0,8)));savedUI();toast('Consulta guardada en este navegador.')}catch(e){toast('El navegador no permite guardar consultas.')}};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(mapExpanded&&map){mapExpanded=false;$('map-pane').classList.remove('map-expanded');map.invalidateSize()}$('inspector').hidden=true;document.querySelector('.app').classList.remove('show-library')}const row=e.target.closest('[data-id]');if(row&&(e.key==='Enter'||e.key===' ')){e.preventDefault();inspect(row.dataset.id)}});
async function boot(){try{const r=await fetch(API+'/api/catalog');if(!r.ok)throw Error('El servidor de datos no está listo. Recargue para volver a conectar.');const d=await r.json();catalog=d.datasets;if(!catalog.some(x=>x.id===S.dataset))S.dataset='presas';if(!['map','series','table','compare','catalog'].includes(S.view))S.view='map';$('archive-total').textContent=fmt(d.total,0)+' registros';$('dataset-count').textContent=catalog.length;$('connection').innerHTML='<i></i>API conectada';savedUI();await render()}catch(e){$('connection').classList.add('failed');$('connection').innerHTML='<i></i>Sin conexión';$('analysis').innerHTML=empty('El servidor de consultas está iniciando.','La primera conexión puede tardar mientras el servicio carga el archivo. Recargue para volver a conectar.');fail(e)}}boot();
})();
